using CourseManagementSystem.Data; using CourseManagementSystem.DTOs.Instructors; using CourseManagementSystem.Models; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace CourseManagementSystem.Controllers; [ApiController][Route("api/[controller]")] public class InstructorsController(ApplicationDbContext context):ControllerBase{
[HttpGet] public async Task<ActionResult<IEnumerable<InstructorResponseDto>>> GetAll()=>Ok(await context.Instructors.AsNoTracking().OrderBy(x=>x.FullName).Select(x=>new InstructorResponseDto(x.Id,x.FullName,x.Email,x.Specialization)).ToListAsync());
[HttpGet("{id:int}")] public async Task<ActionResult<InstructorResponseDto>> GetById(int id){var x=await context.Instructors.AsNoTracking().Where(x=>x.Id==id).Select(x=>new InstructorResponseDto(x.Id,x.FullName,x.Email,x.Specialization)).FirstOrDefaultAsync();return x is null?NotFound():Ok(x);}
[HttpPost] public async Task<ActionResult<InstructorResponseDto>> Create(InstructorCreateDto dto){if(await context.Instructors.AnyAsync(x=>x.Email==dto.Email))return Conflict(new{message="Email already exists."});var x=new Instructor{FullName=dto.FullName.Trim(),Email=dto.Email.Trim(),Specialization=dto.Specialization};context.Add(x);await context.SaveChangesAsync();var r=new InstructorResponseDto(x.Id,x.FullName,x.Email,x.Specialization);return CreatedAtAction(nameof(GetById),new{id=x.Id},r);}
[HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,InstructorUpdateDto dto){var x=await context.Instructors.FindAsync(id);if(x is null)return NotFound();if(await context.Instructors.AnyAsync(i=>i.Id!=id&&i.Email==dto.Email))return Conflict(new{message="Email already exists."});x.FullName=dto.FullName.Trim();x.Email=dto.Email.Trim();x.Specialization=dto.Specialization;await context.SaveChangesAsync();return NoContent();}
[HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var x=await context.Instructors.FindAsync(id);if(x is null)return NotFound();if(await context.Courses.AnyAsync(c=>c.InstructorId==id))return Conflict(new{message="Cannot delete an instructor assigned to courses."});context.Remove(x);await context.SaveChangesAsync();return NoContent();}
}
